# Reading the model the way a person reads it on screen: how big it is, what surfaces
# and edges it has, which layers and notes carry intent, and what accuracy and unit
# system the numbers are expressed in. All observations -- nothing here changes state.
add("geometry bound-box", "geometry", "bound_box", "Read a model's bounding box in its own length units", F, ("xmin", "xmax", "ymin", "ymax", "zmin", "zmax"), {"file": "bracket.prt"}, verifier="observation")
add("geometry surfaces", "geometry", "get_surfaces", "Read surface identities with area and extents; not a tessellation or a BREP export", F, ("surflist",), {"file": "bracket.prt"}, list_key="surflist")
add("geometry edges", "geometry", "get_edges", "Read edge contours for explicitly named surface ids", F | {"surface_ids": {"type": "array", "items": text(pattern=r"^[0-9]{1,10}$"), "minItems": 1, "maxItems": 256}}, ("contourlist",), {"file": "bracket.prt", "surface_ids": ["1"]}, required=("file", "surface_ids"), list_key="contourlist")
add("file accuracy", "file", "get_accuracy", "Read modelling accuracy and whether it is relative or absolute", F, ("accuracy", "relative"), {"file": "bracket.prt"})
add("file unit-system", "file", "get_unit_system", "Read the model's principal unit system name", F, ("name",), {"file": "bracket.prt"})
add("file has-instances", "file", "has_instances", "Check whether a model owns a family table", F, ("exists",), {"file": "bracket.prt"})
add("file simp-reps", "file", "list_simp_reps", "List simplified representations defined on a model", F | {"rep": NAME}, ("reps",), {"file": "bracket.prt"}, required=("file",), list_key="reps")
add("layer list", "layer", "list", "Read layers with their display status", F | {"name": NAME}, ("layers",), {"file": "bracket.prt"}, required=("file",), list_key="layers")
add("layer exists", "layer", "exists", "Check whether a named layer is defined on a model", F | {"name": NAME}, ("exists",), {"file": "bracket.prt", "name": "DATUMS"}, required=("file",))
add("note list", "note", "list", "Read model notes, optionally expanding parameter references", F | {"name": NAME, "get_expanded": BOOL}, ("itemlist",), {"file": "bracket.prt"}, required=("file",), defaults={"select": False}, list_key="itemlist")
add("note get", "note", "get", "Read one named note's text and placement", F | {"name": NAME}, ("name", "value", "encoded", "url", "location"), {"file": "bracket.prt", "name": "NOTE_1"}, required=("file", "name"))
add("note exists", "note", "exists", "Check whether a named note is defined on a model", F | {"name": NAME}, ("exists",), {"file": "bracket.prt", "name": "NOTE_1"}, required=("file",))
add("parameter exists", "parameter", "exists", "Check whether a named parameter is defined on a model", F | {"name": NAME}, ("exists",), {"file": "bracket.prt", "name": "PART_NO"}, required=("file",))
add("feature params", "feature", "list_params", "Read parameters owned by features rather than by the model", F | {"name": NAME, "param": NAME}, ("paramlist",), {"file": "bracket.prt", "name": "HOLE_1"}, required=("file",), defaults={"encoded": False, "inc_unnamed": True}, list_key="paramlist")
add("feature param-exists", "feature", "param_exists", "Check whether a named feature carries a named parameter", F | {"name": NAME, "param": NAME}, ("exists",), {"file": "bracket.prt", "name": "HOLE_1", "param": "DEPTH"}, required=("file", "name"))
add("view list-exploded", "view", "list_exploded", "List exploded assembly states", F | {"name": NAME}, ("viewlist",), {"file": "device.asm"}, required=("file",), list_key="viewlist")

# Family tables: how a mechanical engineer actually ships variants of a part. Reads
# first, then the edits, each naming one exact instance -- no wildcard rows.
# `familytable.list_tree` publishes an `erase` flag that unloads models as a side effect
# of reading; it is pinned false here so a read can never quietly erase a session.
INSTANCE = text(pattern=r"^[A-Za-z0-9_][A-Za-z0-9_-]{0,79}$")
COLUMN = text(pattern=r"^[A-Za-z0-9_][A-Za-z0-9_.()\[\] -]{0,79}$")
FT = {"file": MODEL, "instance": INSTANCE}
add("familytable list", "familytable", "list", "List family-table instance names", F | {"instance": INSTANCE}, ("instances",), {"file": "bracket.prt"}, required=("file",), list_key="instances")
add("familytable exists", "familytable", "exists", "Check whether one named instance exists in a family table", FT, ("exists",), {"file": "bracket.prt", "instance": "bracket_s"}, required=("file", "instance"))
add("familytable header", "familytable", "get_header", "Read family-table column definitions", F, ("columns",), {"file": "bracket.prt"}, list_key="columns")
add("familytable row", "familytable", "get_row", "Read one family-table row by instance name", FT, ("instance", "columns"), {"file": "bracket.prt", "instance": "bracket_s"}, required=("file", "instance"))
add("familytable cell", "familytable", "get_cell", "Read one family-table cell with its declared data type", FT | {"colid": COLUMN}, ("instance", "colid", "value", "datatype", "coltype"), {"file": "bracket.prt", "instance": "bracket_s", "colid": "d1"}, required=("file", "instance", "colid"))
add("familytable parents", "familytable", "get_parents", "Read parent instances of a model in a nested family table", F, ("parents",), {"file": "bracket.prt"}, list_key="parents")
add("familytable tree", "familytable", "list_tree", "Read a nested family-table hierarchy without erasing anything", F, ("total", "children"), {"file": "bracket.prt"}, defaults={"erase": False})

add("familytable create-instance", "familytable", "create_inst", "Materialize one family-table row into a loaded model", FT, ("name",), {"file": "bracket.prt", "instance": "bracket_s"}, required=("file", "instance"), verifier="familytable_created", **W)
add("familytable add-instance", "familytable", "add_inst", "Add one named instance row; upstream creates the family table when absent", FT, (), {"file": "bracket.prt", "instance": "bracket_xl"}, required=("file", "instance"), verifier="familytable_present", **W)
add("familytable set-cell", "familytable", "set_cell", "Set one family-table cell against its expected declared data type", FT | {"colid": COLUMN, "value": PARAM_VALUE, "expected_datatype": text(enum=("STRING", "DOUBLE", "INTEGER", "BOOL"))}, (), {"file": "bracket.prt", "instance": "bracket_s", "colid": "d1", "value": 42, "expected_datatype": "DOUBLE"}, required=("file", "instance", "colid", "value", "expected_datatype"), local_keys=("expected_datatype",), verifier="familytable_cell", **W)
add("familytable replace", "familytable", "replace", "Swap one assembly component for another instance of the same family table", {"file": ASM, "cur_model": MODEL, "cur_inst": INSTANCE, "new_inst": INSTANCE, "path": {"type": "array", "items": text(pattern=r"^[0-9]{1,10}$"), "minItems": 1, "maxItems": 32}}, (), {"file": "device.asm", "cur_model": "bracket.prt", "cur_inst": "bracket_s", "new_inst": "bracket_l"}, required=("file", "cur_model", "new_inst"), target_keys=("file",), verifier="familytable_replaced", **W)
add("familytable delete-instance", "familytable", "delete_inst", "Remove one named instance row from a family table", FT, (), {"file": "bracket.prt", "instance": "bracket_s"}, required=("file", "instance"), verifier="familytable_absent", dangerous=True, **W)
add("familytable delete", "familytable", "delete", "Remove a model's entire family table and every variant it defines", F, (), {"file": "bracket.prt"}, verifier="familytable_table_absent", dangerous=True, **W)

# Drawings, read the way a person inspects a sheet: which sheet and model are current,
# how big the sheet is and at what scale, where each view sits and how large it is, and
# which symbols have been placed. Every target is named explicitly -- the upstream lets
# these default to the active drawing, which this adapter has never allowed.
SYMBOL_FILE = text(pattern=r"^[A-Za-z0-9_][A-Za-z0-9_.-]{0,120}$")
add("drawing current-sheet", "drawing", "get_cur_sheet", "Read which sheet of a drawing is current", D, ("sheet",), {"drawing": "bracket.drw"}, target_keys=("drawing",))
add("drawing current-model", "drawing", "get_cur_model", "Read a drawing's current model", D, ("file",), {"drawing": "bracket.drw"}, target_keys=("drawing",))
add("drawing sheet-size", "drawing", "get_sheet_size", "Read one sheet's size designation", D | {"sheet": SHEET}, ("size",), {"drawing": "bracket.drw", "sheet": 1}, target_keys=("drawing",))
add("drawing sheet-scale", "drawing", "get_sheet_scale", "Read one sheet's scale", D | {"sheet": SHEET, "model": MODEL}, ("scale",), {"drawing": "bracket.drw", "sheet": 1}, required=("drawing", "sheet"), target_keys=("drawing",))
add("drawing sheet-format", "drawing", "get_sheet_format", "Read the format applied to one sheet", D | {"sheet": SHEET}, ("file", "full_name", "common_name"), {"drawing": "bracket.drw", "sheet": 1}, target_keys=("drawing",))
add("drawing list-views", "drawing", "list_views", "List view names on a drawing", D | {"view": NAME}, ("views",), {"drawing": "bracket.drw"}, required=("drawing",), target_keys=("drawing",), list_key="views")
add("drawing view-location", "drawing", "get_view_loc", "Read one view's placement in drawing units", D | {"view": NAME}, ("x", "y", "z"), {"drawing": "bracket.drw", "view": "FRONT_MAIN"}, target_keys=("drawing",))
add("drawing view-scale", "drawing", "get_view_scale", "Read one view's scale", D | {"view": NAME}, ("scale",), {"drawing": "bracket.drw", "view": "FRONT_MAIN"}, target_keys=("drawing",))
add("drawing view-sheet", "drawing", "get_view_sheet", "Read which sheet carries one view", D | {"view": NAME}, ("sheet",), {"drawing": "bracket.drw", "view": "FRONT_MAIN"}, target_keys=("drawing",))
add("drawing view-bound-box", "drawing", "view_bound_box", "Read one view's bounding box in drawing units", D | {"view": NAME}, ("xmin", "xmax", "ymin", "ymax"), {"drawing": "bracket.drw", "view": "FRONT_MAIN"}, target_keys=("drawing",))
add("drawing list-symbols", "drawing", "list_symbols", "List placed symbol instances", D | {"symbol_file": SYMBOL_FILE, "sheet": SHEET}, ("symbols",), {"drawing": "bracket.drw"}, required=("drawing",), target_keys=("drawing",), list_key="symbols")
add("drawing symbol-loaded", "drawing", "is_symbol_def_loaded", "Check whether a symbol definition is loaded in a drawing", D | {"symbol_file": SYMBOL_FILE}, ("loaded",), {"drawing": "bracket.drw", "symbol_file": "note.sym"}, target_keys=("drawing",))

# Drawing edits. Where the upstream lets a target be omitted to mean "all of them"
# -- delete_models without a model, scale_view without a view -- this adapter requires
# the name, the same refusal of wildcard mutations applied everywhere else. View
# coordinates are declared in drawing units, never assumed.
DRAWING_UNITS = text(enum=("drawing_units",))
SYMBOL_ID = text(pattern=r"^[0-9]{1,10}$")
add("drawing select-sheet", "drawing", "select_sheet", "Make one sheet current", D | {"sheet": SHEET}, (), {"drawing": "bracket.drw", "sheet": 1}, target_keys=("drawing",), verifier="drawing_sheet_current", effect="ui", write=True)
add("drawing regenerate-sheet", "drawing", "regenerate_sheet", "Regenerate one sheet; does not certify its dimensions", D | {"sheet": SHEET}, (), {"drawing": "bracket.drw", "sheet": 1}, required=("drawing",), target_keys=("drawing",), verifier="acknowledgement", **W)
add("drawing scale-sheet", "drawing", "scale_sheet", "Set one sheet's scale and read it back", D | {"sheet": SHEET, "scale": POS, "model": MODEL}, (), {"drawing": "bracket.drw", "sheet": 1, "scale": 2}, required=("drawing", "sheet", "scale"), target_keys=("drawing",), verifier="drawing_sheet_scale", **W)
add("drawing set-sheet-format", "drawing", "set_sheet_format", "Apply a format file from the workspace to one sheet", D | {"sheet": SHEET, "file": SYMBOL_FILE, "dirname": PATH}, (), {"drawing": "bracket.drw", "sheet": 1, "file": "a4.drw", "dirname": "templates"}, required=("drawing", "sheet", "file"), target_keys=("drawing",), verifier="drawing_sheet_format", **W)
add("drawing delete-sheet", "drawing", "delete_sheet", "Delete one sheet and everything placed on it", D | {"sheet": SHEET}, (), {"drawing": "bracket.drw", "sheet": 2}, target_keys=("drawing",), verifier="drawing_sheet_count", dangerous=True, **W)
add("drawing set-current-model", "drawing", "set_cur_model", "Make one contained model current in a drawing", D | {"model": MODEL}, (), {"drawing": "bracket.drw", "model": "bracket.prt"}, target_keys=("drawing", "model"), verifier="drawing_model_current", **W)
add("drawing delete-models", "drawing", "delete_models", "Remove one named model from a drawing; the name is required, never all models", D | {"model": MODEL, "delete_views": BOOL}, (), {"drawing": "bracket.drw", "model": "bracket.prt", "delete_views": True}, required=("drawing", "model"), target_keys=("drawing",), verifier="drawing_model_absent", dangerous=True, **W)
add("drawing rename-view", "drawing", "rename_view", "Rename one view and confirm both names moved", D | {"view": NAME, "new_view": NAME}, (), {"drawing": "bracket.drw", "view": "FRONT_MAIN", "new_view": "FRONT_A"}, target_keys=("drawing",), verifier="drawing_view_renamed", **W)
add("drawing move-view", "drawing", "set_view_loc", "Move one view to an explicit position in drawing units", D | {"view": NAME, "point": POINT, "coordinate_units": DRAWING_UNITS}, (), {"drawing": "bracket.drw", "view": "FRONT_MAIN", "point": {"x": 120, "y": 90}, "coordinate_units": "drawing_units"}, target_keys=("drawing",), local_keys=("coordinate_units",), verifier="drawing_view_moved", **W)
add("drawing scale-view", "drawing", "scale_view", "Set one named view's scale; the name is required, never every view at once", D | {"view": NAME, "scale": POS}, ("success_views", "failed_views"), {"drawing": "bracket.drw", "view": "FRONT_MAIN", "scale": 2}, required=("drawing", "view", "scale"), target_keys=("drawing",), verifier="drawing_view_scaled", **W)
add("drawing delete-view", "drawing", "delete_view", "Delete one named view; child views are kept unless asked for", D | {"view": NAME, "sheet": SHEET, "del_children": BOOL}, (), {"drawing": "bracket.drw", "view": "RIGHT_PROJECTED"}, required=("drawing", "view"), target_keys=("drawing",), defaults={"del_children": False}, verifier="drawing_view_absent", dangerous=True, **W)
add("drawing load-symbol", "drawing", "load_symbol_def", "Load a symbol definition from the workspace into a drawing", D | {"symbol_file": SYMBOL_FILE, "symbol_dir": PATH}, ("id", "name"), {"drawing": "bracket.drw", "symbol_file": "note.sym", "symbol_dir": "templates"}, required=("drawing", "symbol_file"), target_keys=("drawing",), verifier="drawing_symbol_loaded", **W)
add("drawing place-symbol", "drawing", "create_symbol", "Place one loaded symbol at an explicit point in drawing units", D | {"symbol_file": SYMBOL_FILE, "point": POINT, "sheet": SHEET, "coordinate_units": DRAWING_UNITS, "replace_values": {"type": "object", "additionalProperties": text(maximum=512), "maxProperties": 32}}, (), {"drawing": "bracket.drw", "symbol_file": "note.sym", "point": {"x": 50, "y": 20}, "sheet": 1, "coordinate_units": "drawing_units"}, required=("drawing", "symbol_file", "point", "coordinate_units"), target_keys=("drawing",), local_keys=("coordinate_units",), verifier="drawing_symbol_placed", **W)
add("drawing delete-symbol-definition", "drawing", "delete_symbol_def", "Unload a symbol definition and every instance of it", D | {"symbol_file": SYMBOL_FILE}, (), {"drawing": "bracket.drw", "symbol_file": "note.sym"}, target_keys=("drawing",), verifier="drawing_symbol_definition_absent", dangerous=True, **W)
add("drawing delete-symbol-instance", "drawing", "delete_symbol_inst", "Delete one placed symbol instance by id", D | {"symbol_id": SYMBOL_ID}, (), {"drawing": "bracket.drw", "symbol_id": "1"}, target_keys=("drawing",), verifier="drawing_symbol_instance_absent", dangerous=True, **W)

# Editing the model. Two upstream defaults are refused outright here:
# `file.erase_not_displayed` takes no target at all and erases whatever is not on
# screen, and the unit setters carry a `convert` flag that decides whether 40 mm
# becomes 40 in or 1.575 in. That flag is required with no default -- reinterpreting
# every dimension in a model is not something to inherit from a wire default.
MATERIAL_GLOB = text(pattern=r"^[A-Za-z0-9_*?][A-Za-z0-9_.*?-]{0,79}$")
RELATIONS = {"type": "array", "items": text(maximum=512), "maxItems": 2000}
CONVERT = {"type": "boolean"}
add("file mass-units-only", "file", "get_mass_units", "Read only the mass units, without the length units file units also returns", F, ("units",), {"file": "bracket.prt"})
add("file materials-wildcard", "file", "list_materials_wildcard", "List materials matching a bounded pattern across loaded parts", {"file": PART, "material": MATERIAL_GLOB, "include_non_matching_parts": BOOL}, ("materials",), {"file": "bracket.prt", "material": "*"}, required=("file",), list_key="materials")
add("file current-material-wildcard", "file", "get_cur_material_wildcard", "Read assigned materials across loaded parts", {"file": PART, "include_non_matching_parts": BOOL}, ("materials",), {"file": "bracket.prt"}, required=("file",), list_key="materials")
add("file postregen-relations", "file", "postregen_relations_get", "Read post-regeneration relations without evaluating them", F, ("relations",), {"file": "bracket.prt"}, list_key="relations")

add("file rename", "file", "rename", "Rename a model, choosing explicitly whether the disk file moves too", F | {"new_name": MODEL, "onlysession": BOOL}, ("file",), {"file": "bracket.prt", "new_name": "bracket_v2.prt", "onlysession": True}, required=("file", "new_name", "onlysession"), verifier="renamed", effect="disk_and_memory", write=True)
add("file erase", "file", "erase", "Remove one named model from session memory; unsaved changes in it are lost", F | {"erase_children": BOOL}, (), {"file": "bracket.prt", "erase_children": False}, required=("file", "erase_children"), verifier="erased", dangerous=True, **W)
add("file set-length-units", "file", "set_length_units", "Set length units, stating whether existing geometry is converted or reinterpreted", F | {"units": LENGTH, "convert": CONVERT}, (), {"file": "bracket.prt", "units": "mm", "convert": True}, required=("file", "units", "convert"), verifier="length_units", **W)
add("file set-mass-units", "file", "set_mass_units", "Set mass units, stating whether existing values are converted or reinterpreted", F | {"units": text(enum=("g", "kg", "lb", "oz", "tonne")), "convert": CONVERT}, (), {"file": "bracket.prt", "units": "kg", "convert": True}, required=("file", "units", "convert"), verifier="mass_units", **W)
add("file set-unit-system", "file", "set_unit_system", "Apply a named unit system, stating whether existing values are converted", F | {"name": NAME, "convert": CONVERT}, (), {"file": "bracket.prt", "name": "mmNs", "convert": True}, required=("file", "name", "convert"), verifier="unit_system", **W)
add("file create-unit-system", "file", "create_unit_system", "Define a new named unit system on a model", F | {"name": NAME, "unit_length": LENGTH, "unit_mass": text(enum=("g", "kg", "lb", "oz", "tonne")), "unit_time": text(enum=("sec", "min", "hr")), "unit_temp": text(enum=("C", "F", "K", "R"))}, (), {"file": "bracket.prt", "name": "custom_mmks", "unit_length": "mm", "unit_mass": "kg", "unit_time": "sec", "unit_temp": "C"}, required=("file", "name", "unit_length", "unit_mass", "unit_time", "unit_temp"), verifier="acknowledgement", **W)
add("file load-material", "file", "load_material_file", "Load a material definition from the workspace into a part", {"file": PART, "material": NAME, "dirname": PATH}, ("files",), {"file": "bracket.prt", "material": "TITANIUM", "dirname": "."}, required=("file", "material"), verifier="material_present", **W)
add("file delete-material", "file", "delete_material", "Remove one material definition from a part", {"file": PART, "material": NAME}, ("files",), {"file": "bracket.prt", "material": "STEEL"}, required=("file", "material"), verifier="material_absent", dangerous=True, **W)
add("file set-relations", "file", "relations_set", "Replace a model's relations wholesale; the CLI does not evaluate the text", F | {"relations": RELATIONS}, (), {"file": "bracket.prt", "relations": ["d1 = 45"]}, required=("file", "relations"), verifier="relations", dangerous=True, **W)
add("file set-postregen-relations", "file", "postregen_relations_set", "Replace post-regeneration relations wholesale", F | {"relations": RELATIONS}, (), {"file": "bracket.prt", "relations": ["d2 = d1 / 8"]}, required=("file", "relations"), verifier="postregen_relations", dangerous=True, **W)

add("parameter copy", "parameter", "copy", "Copy one parameter to another name or model", F | {"name": NAME, "to_name": NAME, "to_file": MODEL, "designate": BOOL}, (), {"file": "bracket.prt", "name": "PART_NO", "to_name": "PART_NO_REV"}, required=("file", "name", "to_name"), target_keys=("file",), verifier="parameter_copied", **W)
