add("dimension copy", "dimension", "copy", "Copy one dimension to another name or model", F | {"name": NAME, "to_name": NAME, "to_file": MODEL}, (), {"file": "bracket.prt", "name": "d1", "to_name": "d1_copy"}, required=("file", "name", "to_name"), target_keys=("file",), verifier="dimension_copied", **W)
add("dimension set-text", "dimension", "set_text", "Set one dimension's display text without changing its value", F | {"name": NAME, "text": text(maximum=512)}, (), {"file": "bracket.prt", "name": "d1", "text": "45 REF"}, required=("file", "name", "text"), defaults={"encoded": False}, verifier="dimension_text", **W)
add("dimension show", "dimension", "show", "Show or hide one dimension, optionally through an explicit assembly path", F | {"name": NAME, "assembly": ASM, "path": {"type": "array", "items": text(pattern=r"^[0-9]{1,10}$"), "minItems": 1, "maxItems": 32}, "show": BOOL}, (), {"file": "bracket.prt", "name": "d1", "show": True}, required=("file", "name", "show"), verifier="acknowledgement", effect="ui", write=True)

add("feature delete", "feature", "delete", "Delete exactly one named feature; never a status or type sweep", F | {"name": NAME}, (), {"file": "bracket.prt", "name": "HOLE_1"}, required=("file", "name"), defaults={"clip": False}, verifier="feature_absent", dangerous=True, **W)
add("feature set-param", "feature", "set_param", "Set one typed parameter on one named feature", F | {"name": NAME, "param": NAME, "type": text(enum=("STRING", "DOUBLE", "INTEGER", "BOOL")), "value": PARAM_VALUE, "designate": BOOL}, (), {"file": "bracket.prt", "name": "HOLE_1", "param": "DEPTH", "type": "STRING", "value": "THRU"}, required=("file", "name", "param", "type", "value"), defaults={"encoded": False, "no_create": False}, verifier="feature_param", **W)
