add("feature group-features", "feature", "list_group_features", "List the features inside one named group", F | {"group_name": NAME, "type": NAME}, ("featlist",), {"file": "bracket.prt", "group_name": "GROUP_1"}, required=("file", "group_name"), list_key="featlist")
add("feature pattern-features", "feature", "list_pattern_features", "List the features produced by one named pattern", F | {"pattern_name": NAME, "type": NAME}, ("featlist",), {"file": "bracket.prt", "pattern_name": "PATTERN_1"}, required=("file", "pattern_name"), list_key="featlist")

add("note set", "note", "set", "Create or update one named note's text", F | {"name": NAME, "value": text(maximum=4000), "location": POINT}, (), {"file": "bracket.prt", "name": "NOTE_1", "value": "BREAK SHARP EDGES"}, required=("file", "name", "value"), defaults={"encoded": False}, verifier="note_present", **W)
add("note copy", "note", "copy", "Copy one note to another name or model", F | {"name": NAME, "to_name": NAME, "to_file": MODEL}, (), {"file": "bracket.prt", "name": "NOTE_1", "to_name": "NOTE_2"}, required=("file", "name", "to_name"), target_keys=("file",), verifier="note_copied", **W)
add("note delete", "note", "delete", "Delete one named note", F | {"name": NAME}, (), {"file": "bracket.prt", "name": "NOTE_1"}, required=("file", "name"), verifier="note_absent", dangerous=True, **W)

